	try {
		const folder = params && params.folder;
		if (typeof folder !== 'string') {
			throw new Error('[[error:invalid-path]]');
		}

		const uploadRoot = path.resolve(nconf.get('upload_path'));
		const uploadDirectory = path.resolve(path.join(uploadRoot, folder));
		const relativeUploadDirectory = path.relative(uploadRoot, uploadDirectory);
		if (relativeUploadDirectory === '..' || relativeUploadDirectory.startsWith(`..${path.sep}`) || path.isAbsolute(relativeUploadDirectory)) {
			throw new Error('[[error:invalid-path]]');
		}

		try {
			const stats = await fs.promises.stat(uploadDirectory);
			if (!stats.isDirectory()) {
				throw new Error('[[error:invalid-path]]');
			}
		} catch (err) {
			if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
				throw new Error('[[error:invalid-path]]');
			}
			throw err;
		}

		const data = await file.saveFileToLocal(uploadedFile.name, folder, uploadedFile.path);
		res.json([{ url: data.url }]);
	} catch (err) {
		next(err);
	} finally {
		file.delete(uploadedFile.path);
	}
};

